//! Documents written by older releases: they load, migrate (owner, run policy) and render
//! exactly the units they rendered before (golden files `src/golden/compat/`, generated by
//! rynas 0.8.13 from the same document).

use rynas_api_types::scheduler::{
    LockedField, MissedPolicy, Overlap, OwnerFeature, Recurrence, Retry, ScheduledTask,
    SchedulerConfig, TaskAction, TaskOwner, TaskTrigger,
};
use rynas_schedule::{TimeOfDay, Weekdays};

use super::{apply, calendar, env, golden, read, stage, task};
use crate::domain::{SCHEDULER_KEY, normalize_task};

/// A `scheduler` document as rynas 0.8.13 stored it (every kind of task, the way each
/// feature writes its tasks).
const STORED_0_8_13: &str = r#"{"tasks":[
 {"id":"snapshot-docs","name":"Snapshots of docs","description":"","enabled":true,"action":{"kind":"snapshot","job":"docs"},"trigger":{"kind":"calendar","on_calendar":"hourly","persistent":true,"randomized_delay_s":0},"timeout_s":null,"nice":null,"io_weight":null,"notify":"on_failure","notify_output":false},
 {"id":"replicate-docs-usb","name":"Replica docs to usb","description":"","enabled":true,"action":{"kind":"replicate","job":"docs","target":"usb"},"trigger":{"kind":"calendar","on_calendar":"*-*-* 01:30:00","persistent":true,"randomized_delay_s":600},"timeout_s":null,"nice":null,"io_weight":null,"notify":"on_failure","notify_output":false},
 {"id":"backup-offsite","name":"Backup offsite","description":"","enabled":true,"action":{"kind":"backup","job":"offsite"},"trigger":{"kind":"calendar","on_calendar":"Mon..Fri *-*-* 02:30:00","persistent":true,"randomized_delay_s":0},"timeout_s":null,"nice":null,"io_weight":null,"notify":"on_failure","notify_output":false},
 {"id":"power-off-night","name":"Scheduled shutdown","description":"","enabled":true,"action":{"kind":"power_shutdown","rule":"night"},"trigger":{"kind":"calendar","on_calendar":"Mon,Tue,Wed,Thu,Fri *-*-* 23:30:00","persistent":false,"randomized_delay_s":0},"timeout_s":null,"nice":null,"io_weight":null,"notify":"on_failure","notify_output":false},
 {"id":"dedup-vol1","name":"Deduplication vol1","description":"","enabled":false,"action":{"kind":"dedup","volume":"vol1"},"trigger":{"kind":"calendar","on_calendar":"Sat,Sun *-*-* 01,02,03:00:00","persistent":false,"randomized_delay_s":0},"timeout_s":null,"nice":null,"io_weight":null,"notify":"never","notify_output":false},
 {"id":"scrub-vol1","name":"Scrub","description":"monthly","enabled":true,"action":{"kind":"scrub","filesystem":"/srv/vol1"},"trigger":{"kind":"calendar","on_calendar":"*-*-01 04:00:00"},"timeout_s":86400,"nice":5,"io_weight":20,"notify":"always","notify_output":true},
 {"id":"recycle","name":"recycle","description":"","enabled":true,"action":{"kind":"recycle_cleanup"},"trigger":{"kind":"calendar","on_calendar":"daily","persistent":false,"randomized_delay_s":3600},"notify":"on_failure"},
 {"id":"hello","action":{"kind":"command","command":"echo hello"},"trigger":{"kind":"boot"}},
 {"id":"smart-sda","name":"smart","enabled":true,"action":{"kind":"smart_test","disk":"sda","test":"long"},"trigger":{"kind":"manual"}}
]}"#;

#[test]
fn documents_of_older_releases_render_the_same_units() {
    let e = env();
    e.cfg
        .stage(
            "admin",
            SCHEDULER_KEY,
            Some(serde_json::from_str(STORED_0_8_13).unwrap()),
        )
        .unwrap();
    apply(&e).unwrap();
    let units = "/etc/systemd/system";
    for id in [
        "snapshot-docs",
        "replicate-docs-usb",
        "backup-offsite",
        "power-off-night",
        "dedup-vol1",
        "scrub-vol1",
        "recycle",
        "hello",
    ] {
        for ext in ["service", "timer"] {
            golden(
                &format!("compat/{id}.{ext}"),
                &read(&e.root, &format!("{units}/rynas-task-{id}.{ext}")),
            );
        }
    }
    golden(
        "compat/rynas-tasks.conf",
        &read(&e.root, "/etc/systemd/system/timers.target.d/rynas-tasks.conf"),
    );
    assert!(!e.root.join("etc/systemd/system/rynas-task-smart-sda.timer").exists());
}

#[test]
fn migrated_documents_keep_their_timers_running() {
    let e = env();
    e.cfg
        .stage("admin", SCHEDULER_KEY, Some(serde_json::from_str(STORED_0_8_13).unwrap()))
        .unwrap();
    apply(&e).unwrap();
    // stored as validated: owner and policy filled in, trigger fields unchanged
    let doc = e.cfg.applied(SCHEDULER_KEY).unwrap().unwrap();
    let tasks = crate::domain::tasks_of(Some(&doc));
    let power = tasks.iter().find(|t| t.id == "power-off-night").unwrap();
    assert_eq!(
        power.owner,
        TaskOwner::Feature { feature: OwnerFeature::Power, key: "night".into() }
    );
    assert_eq!(power.policy.missed, Some(MissedPolicy::Skip));
    assert_eq!(power.owner.locked(), [LockedField::Action, LockedField::Schedule, LockedField::Missed]);
    let rep = tasks.iter().find(|t| t.id == "replicate-docs-usb").unwrap();
    assert_eq!(rep.policy.jitter_s, Some(600));
    assert_eq!(rep.effective_policy().retry, Retry::TRANSFER);
    let scrub = tasks.iter().find(|t| t.id == "scrub-vol1").unwrap();
    assert_eq!(scrub.owner, TaskOwner::User);
    assert_eq!(scrub.policy.missed, Some(MissedPolicy::RunOnce { within_h: None }));
    assert_eq!(scrub.effective_policy().retry, Retry::NONE);
    assert_eq!(scrub.effective_policy().overlap, Overlap::Skip);
    // staging the migrated tasks again (what any later change does) restarts no timer and
    // changes no file
    e.sys.state().calls.clear();
    let mut again = tasks.clone();
    again.iter_mut().for_each(|t| t.description.push('.'));
    stage(&e, again).unwrap();
    apply(&e).unwrap();
    let calls = e.sys.state().calls.clone();
    assert!(!calls.iter().any(|c| c.contains("restart")), "{calls:?}");
    assert!(calls.iter().any(|c| c == "run systemctl start --no-block rynas-task-backup-offsite.timer"), "{calls:?}");
    assert!(e.cfg.drift().unwrap().entries.is_empty());
}

#[test]
fn run_policy_and_new_triggers() {
    let base = task("t", TaskAction::Command { command: "true".into(), user: "root".into() }, calendar("daily"));
    // a preset is stored as its expression; the policy gives catch-up and delay
    let mut t = base.clone();
    t.trigger = TaskTrigger::Recurrence {
        recurrence: Recurrence::Daily { days: Weekdays::MON_FRI, times: vec![TimeOfDay::new(2, 30)] },
    };
    t.policy.missed = Some(MissedPolicy::Skip);
    t.policy.jitter_s = Some(300);
    let n = normalize_task(t).unwrap();
    assert_eq!(
        n.trigger,
        TaskTrigger::Calendar {
            on_calendar: "Mon..Fri *-*-* 02:30:00".into(),
            cron: None,
            persistent: false,
            randomized_delay_s: 300
        }
    );
    let timer = crate::units::render_timer(&n).unwrap();
    assert!(timer.contains("OnCalendar=Mon..Fri *-*-* 02:30:00\nRandomizedDelaySec=300\n"), "{timer}");
    // the policy is the reference when it is there, and the trigger fields follow it
    let mut t = base.clone();
    t.policy.missed = Some(MissedPolicy::RunOnce { within_h: Some(12) });
    if let TaskTrigger::Calendar { persistent, .. } = &mut t.trigger {
        *persistent = false;
    }
    let n = normalize_task(t).unwrap();
    assert!(matches!(n.trigger, TaskTrigger::Calendar { persistent: true, .. }));
    assert!(crate::units::render_timer(&n).unwrap().contains("Persistent=true\n"));
    // not run by the Task Scheduler yet
    for trig in [
        TaskTrigger::Interval { hours: 24, after_boot_min: 10 },
        TaskTrigger::Window { window: "1".repeat(168), stop_at_end: true },
        TaskTrigger::After { task: "snapshot-docs".into(), only_on_success: true },
    ] {
        let mut t = base.clone();
        t.trigger = trig;
        assert!(normalize_task(t).unwrap_err().contains("not supported"));
    }
    // bounds
    let mut t = base.clone();
    t.policy.missed = Some(MissedPolicy::RunOnce { within_h: Some(0) });
    assert!(normalize_task(t).is_err());
    let mut t = base.clone();
    t.policy.retry = Some(Retry { attempts: 11, ..Retry::TRANSFER });
    assert!(normalize_task(t).is_err());
    let mut t = base;
    t.policy.notify.after_failures = 0;
    assert!(normalize_task(t).is_err());
}

#[test]
fn the_model_reads_and_writes_older_documents() {
    let old: SchedulerConfig = serde_json::from_str(STORED_0_8_13).unwrap();
    // nothing new is written for a task that does not use it
    let t = &old.tasks[0];
    assert!(t.owner.is_user() && t.policy.is_empty());
    let v = serde_json::to_value(t).unwrap();
    assert!(v.get("owner").is_none() && v.get("policy").is_none(), "{v}");
    // a migrated task round-trips
    let mut m = t.clone();
    m.migrate();
    let mut again = m.clone();
    again.migrate();
    assert_eq!(again, m, "idempotent");
    let back: ScheduledTask = serde_json::from_value(serde_json::to_value(&m).unwrap()).unwrap();
    assert_eq!(back, m);
    let v = serde_json::to_value(&m).unwrap();
    assert_eq!(v["owner"], serde_json::json!({"kind": "feature", "feature": "snapshots", "key": "docs"}));
    assert_eq!(v["policy"], serde_json::json!({"missed": {"kind": "run_once"}, "jitter_s": 0}));
    let r: TaskTrigger = serde_json::from_value(serde_json::json!(
        {"kind": "recurrence", "recurrence": {"kind": "hours", "every": 6, "minute": 15, "from": 0, "to": 23, "days": 0}}
    ))
    .unwrap();
    assert_eq!(r.on_calendar().as_deref(), Some("*-*-* 00/6:15:00"));
}
